messages.content:
Tool response:
Tool: submit_insurance_claim
Description: Submit Insurance Claim
Parameters:
    {
      "type": "object",
      "properties": {
        "claim_number": {
          "type": "string",
          "title": "Claim Number"
        },
        "patient_id": {
          "type": "integer",
          "title": "Patient Id"
        },
        "policy_id": {
          "type": "integer",
          "title": "Policy Id"
        },
        "payer_id": {
          "type": "integer",
          "title": "Payer Id"
        },
        "total_billed_amount": {
          "type": "number",
          "title": "Total Billed Amount"
        },
        "procedures": {
          "items": {
            "properties": {
              "procedure_code": {
                "type": "string",
                "title": "Procedure Code"
              },
              "description": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Description"
              },
              "billed_amount": {
                "type": "number",
                "title": "Billed Amount"
              },
              "tooth_number": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Tooth Number"
              },
              "surface": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Surface"
              }
            },
            "type": "object",
            "required": [
              "procedure_code",
              "billed_amount"
            ],
            "title": "ProcedureItem"
          },
          "type": "array",
          "title": "Procedures"
        },
        "notes": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Notes"
        }
      },
      "required": [
        "claim_number",
        "patient_id",
        "policy_id",
        "payer_id",
        "total_billed_amount",
        "procedures"
      ]
    }
